def run(self, c: Compaction) -> None:
    out = c.level + 1
    outputs: list[SSTable] = []
    builder: TableBuilder | None = None
    for key, value in merge(t.items() for t in c.inputs + c.overlaps):  # newest first
        if value is None and not self._deeper_may_hold(out, key):
            continue  # a tombstone with nothing left to hide
        if builder is None:
            builder = TableBuilder(self.levels.table_path(), self.opts.block_bytes, self.opts.bloom_bits_per_key)
        builder.add(key, value)
        if builder.size >= self.opts.table_bytes:
            outputs.append(builder.finish())
            builder = None
    if builder is not None:
        outputs.append(builder.finish())
    self.bytes_written += sum(t.size for t in outputs)

    # Swap inputs for outputs in one commit; until it lands, the old tables are the database.
    levels = self.levels.levels
    levels[c.level] = [t for t in levels[c.level] if t not in c.inputs]
    kept = [t for t in levels[out] if t not in c.overlaps]
    levels[out] = sorted(kept + outputs, key=lambda t: t.min_key)
    self.levels.commit()
    for table in c.inputs + c.overlaps:
        table.path.unlink()  # a scan still reading it keeps its open file (POSIX)

def get(self, key: bytes) -> bytes | None:
    """The newest value of key, or None if it was never written or was deleted."""
    found = self._mem.get(key)
    if found is not MISSING:
        return found  # bytes, or None for a tombstone
    for table in self._levels.tables_for_key(key):  # newest first
        found = table.get(key)  # the bloom filter skips most tables without a disk read
        if found is not MISSING:
            return found
    return None

def scan(self, start: bytes | None = None, end: bytes | None = None) -> Iterator[tuple[bytes, bytes]]:
    """Live (key, value) pairs with start <= key < end, in key order, as of now."""
    sources = [self._mem.items(start, end)]  # newest
    sources += [t.items(start, end) for t in self._levels.tables_for_range(start, end)]
    return live(merge(sources))

@classmethod
def load(cls, directory: Path, num_levels: int) -> "Levels":
    levels = cls(directory, num_levels)
    path = directory / MANIFEST
    if path.exists():
        state = json.loads(path.read_text())
        levels.next_number, levels.log_number = state["next_number"], state["log_number"]
        for n, names in enumerate(state["levels"]):
            levels.levels[n] = [SSTable(directory / name) for name in names]
    else:
        levels.log_number = levels.new_number()
        levels.commit()
    levels._delete_debris()
    return levels

def _delete_debris(self) -> None:
    named = {table.path.name for level in self.levels for table in level}
    for path in self.dir.iterdir():
        if path.suffix == ".sst" and path.name not in named:
            path.unlink()  # written by a flush or compaction that never committed
        elif path.suffix == ".log" and path.stem.isdigit() and int(path.stem) < self.log_number:
            path.unlink()  # already flushed to a table
